sys_ui_action.script:
(function() {
    try {
        var obj = "Engagement request " + current.getValue('number') +
            " entered 'Need more information'. Record sys_id: " + current.getUniqueValue() +
            ". Review it for missing or weak intake signals and append ONE work note draft " +
            "(the write tool prefixes it with [AI Completeness Draft]) listing at most three " +
            "specific gaps in requester-friendly wording. Journal write only; change no fields.";
        var resp = new sn_aia.AiAgentRuntimeUtil().startAiAgentConversation({
            targetRecordId: current.getUniqueValue(),
            targetTable: 'x_snc_ptag_engage_engagement_request',
            objective: obj,
            usecaseId: '0c6e958d871a0b90e5790f29dabb357c',
            conversationUser: gs.getUserID()
        });
        if (resp && resp.status === 'success') {
            gs.addInfoMessage(gs.getMessage('Completeness check started; the [AI Completeness Draft] work note will appear shortly.'));
        } else {
            gs.addErrorMessage(gs.getMessage('Completeness check did not start: {0}', JSON.stringify(resp && resp.error)));
        }
    } catch (e) {
        gs.addErrorMessage(gs.getMessage('Could not start completeness check: {0}', '' + e));
    }
    action.setRedirectURL(current);
})();
